def test(
    obj: dict,
    fail_fast: bool,
    cov: bool,
    cov_fail_under: int,
    base_ref: str,
    workers: int,
    package_names: tuple,
):
    # Fail on incompatible configurations
    if cov_fail_under and not cov:
        raise click.UsageError(
            "You have to pass --cov in order to use --cov-fail-under"
        )

    if base_ref is not None and not base_ref:
        raise click.UsageError("Option '--base-ref' cannot be empty.")

    if not package_names and not base_ref:
        raise click.UsageError(
            "Either pass '--base-ref' or provide at least one package name."
        )

    console = obj["console"]
    repo_root = obj["repo_root"]
    debug: bool = obj["debug"]
    packages_to_test: set[Path] = set()
    all_packages = find_all_packages(repo_root)

    if package_names:
        changed_packages: set[Path] = {repo_root / Path(pn) for pn in package_names}
    else:
        # Get the files that changed from the base branch
        changed_files = get_changed_files(repo_root, base_ref)
        # Get the packages containing the changed files
        changed_packages = get_changed_packages(changed_files, all_packages)

    # Find the dependants of the changed packages
    # Skip dependants if we're checking coverage
    if cov:
        dependants = set()
    else:
        dependants = get_dependants_packages(changed_packages, all_packages)

    # Test the packages directly affected and their dependants
    packages_to_test = changed_packages | dependants

    # Test the packages using a process pool
    results = []
    with concurrent.futures.ProcessPoolExecutor(max_workers=int(workers)) as executor:
        future_to_package = {
            executor.submit(
                _run_tests,
                package_path,
                changed_packages,
                base_ref,
                cov,
                cov_fail_under,
            ): package_path
            for package_path in sorted(packages_to_test)
        }

        for future in concurrent.futures.as_completed(future_to_package):
            result = future.result()
            results.append(result)

            # Print results as they complete
            package: Path = result["package"]
            package_name = package.relative_to(repo_root)
            if result["status"] == ResultStatus.INSTALL_FAILED:
                console.print(f"❗ Unable to build package {package_name}")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            elif result["status"] == ResultStatus.TESTS_PASSED:
                console.print(f"✅ {package_name} succeeded in {result['time']}")
            elif result["status"] == ResultStatus.UNSUPPORTED_PYTHON_VERSION:
                console.print(
                    f"⏭️ {package_name} skipped due to python version incompatibility"
                )
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            elif result["status"] == ResultStatus.NO_TESTS:
                console.print(f"⏭️ {package_name} skipped due to no tests")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            else:
                console.print(f"❌ {package_name} failed")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="error"
                )
                console.print(
                    _trim(debug, f"Output:\n{result['stdout']}"), style="info"
                )

    # Print summary
    failed = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] in (ResultStatus.TESTS_FAILED, ResultStatus.COVERAGE_FAILED)
    ]
    install_failed = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.INSTALL_FAILED
    ]
    skipped_no_tests = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.NO_TESTS
        and "package has no tests" in r["stderr"]
    ]
    skipped_pyversion_incompatible = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.UNSUPPORTED_PYTHON_VERSION
        and "Not compatible with Python" in r["stderr"]
    ]

    if skipped_pyversion_incompatible:
        console.print(
            f"\n{len(skipped_pyversion_incompatible)} packages were skipped due to Python version incompatibility:"
        )
        for p in skipped_pyversion_incompatible:
            print(p)
    if skipped_no_tests:
        console.print(
            f"\n{len(skipped_no_tests)} packages were skipped because they have no tests:"
        )
        for p in skipped_no_tests:
            print(p)

    if install_failed:
        # Do not fail the CI if there was an installation problem: many packages cannot
        # be installed in the runners, something we should either fix or ignore.
        console.print(f"\n{len(install_failed)} packages could not be installed:")
        for p in install_failed:
            print(p)

    if failed:
        console.print(f"\n{len(failed)} packages had test failures:")
        for p in failed:
            console.print(p)
        exit(1)
    else:
        console.print(
            f"\nTests passed for {len(results) - len(skipped_no_tests) - len(skipped_pyversion_incompatible)} packages.",
            style="green",
        )

class MediaPipeline(ABC):
    crawler: Crawler
    _fingerprinter: RequestFingerprinterProtocol
    _modern_init = False

    LOG_FAILED_RESULTS: bool = True

    class SpiderInfo:
        def __init__(self, spider: Spider):
            self.spider: Spider = spider
            self.downloading: set[bytes] = set()
            self.downloaded: dict[bytes, FileInfo | Failure] = {}
            self.waiting: defaultdict[bytes, list[Deferred[FileInfo]]] = defaultdict(
                list
            )

    def __init__(
        self,
        download_func: Callable[[Request, Spider], Response] | None = None,
        settings: Settings | dict[str, Any] | None = None,
        *,
        crawler: Crawler | None = None,
    ):
        self.download_func = download_func

        if crawler is not None:
            if settings is not None:
                warnings.warn(
                    f"MediaPipeline.__init__() was called with a crawler instance and a settings instance"
                    f" when creating {global_object_name(self.__class__)}. The settings instance will be ignored"
                    f" and crawler.settings will be used. The settings argument will be removed in a future Scrapy version.",
                    category=ScrapyDeprecationWarning,
                    stacklevel=2,
                )
            settings = crawler.settings
        elif isinstance(settings, dict) or settings is None:
            settings = Settings(settings)
        resolve = functools.partial(
            self._key_for_pipe, base_class_name="MediaPipeline", settings=settings
        )
        self.allow_redirects: bool = settings.getbool(
            resolve("MEDIA_ALLOW_REDIRECTS"), False
        )
        self._handle_statuses(self.allow_redirects)

        if crawler:
            self._finish_init(crawler)
            self._modern_init = True
        else:
            warnings.warn(
                f"MediaPipeline.__init__() was called without the crawler argument"
                f" when creating {global_object_name(self.__class__)}."
                f" This is deprecated and the argument will be required in future Scrapy versions.",
                category=ScrapyDeprecationWarning,
                stacklevel=2,
            )

    def _finish_init(self, crawler: Crawler) -> None:
        # This was done in from_crawler() before 2.12, now it's done in __init__()
        # if the crawler was passed to it and may be needed to be called in other
        # deprecated code paths explicitly too. After the crawler argument of __init__()
        # becomes mandatory this should be inlined there.
        self.crawler = crawler
        assert crawler.request_fingerprinter
        self._fingerprinter = crawler.request_fingerprinter

    def _handle_statuses(self, allow_redirects: bool) -> None:
        self.handle_httpstatus_list = None
        if allow_redirects:
            self.handle_httpstatus_list = SequenceExclude(range(300, 400))

    def _key_for_pipe(
        self,
        key: str,
        base_class_name: str | None = None,
        settings: Settings | None = None,
    ) -> str:
        class_name = self.__class__.__name__
        formatted_key = f"{class_name.upper()}_{key}"
        if (
            not base_class_name
            or class_name == base_class_name
            or (settings and not settings.get(formatted_key))
        ):
            return key
        return formatted_key

    @classmethod
    def from_crawler(cls, crawler: Crawler) -> Self:
        pipe: Self
        if hasattr(cls, "from_settings"):
            pipe = cls.from_settings(crawler.settings)  # type: ignore[attr-defined]
            warnings.warn(
                f"{global_object_name(cls)} has from_settings() and either doesn't have"
                " from_crawler() or calls MediaPipeline.from_crawler() from it,"
                " so from_settings() was used to create the instance of it."
                " This is deprecated and calling from_settings() will be removed"
                " in a future Scrapy version. Please move the initialization code into"
                " from_crawler() or __init__().",
                category=ScrapyDeprecationWarning,
            )
        elif "crawler" in get_func_args(cls.__init__):
            pipe = cls(crawler=crawler)
        else:
            pipe = cls()
            warnings.warn(
                f"{global_object_name(cls)}.__init__() doesn't take a crawler argument."
                " This is deprecated and the argument will be required in future Scrapy versions.",
                category=ScrapyDeprecationWarning,
            )
        if not pipe._modern_init:
            pipe._finish_init(crawler)
        return pipe

    @_warn_spider_arg
    def open_spider(self, spider: Spider | None = None) -> None:
        assert self.crawler.spider
        self.spiderinfo = self.SpiderInfo(self.crawler.spider)

    @_warn_spider_arg
    def process_item(
        self, item: Any, spider: Spider | None = None
    ) -> Deferred[list[FileInfoOrError]]:
        info = self.spiderinfo
        requests = arg_to_iter(self.get_media_requests(item, info))
        dlist = [self._process_request(r, info, item) for r in requests]
        dfd = cast(
            "Deferred[list[FileInfoOrError]]", DeferredList(dlist, consumeErrors=True)
        )
        return dfd.addCallback(self.item_completed, item, info)

    @inlineCallbacks
    def _process_request(
        self, request: Request, info: SpiderInfo, item: Any
    ) -> Generator[Deferred[Any], Any, FileInfo]:
        fp = self._fingerprinter.fingerprint(request)

        eb = request.errback
        request.callback = NO_CALLBACK
        request.errback = None

        # Return cached result if request was already seen
        if fp in info.downloaded:
            yield _defer_sleep()
            cached_result = info.downloaded[fp]
            if isinstance(cached_result, Failure):
                if eb:
                    return eb(cached_result)
                cached_result.raiseException()
            return cached_result

        # Otherwise, wait for result
        wad: Deferred[FileInfo] = Deferred()
        if eb:
            wad.addErrback(eb)
        info.waiting[fp].append(wad)

        # Check if request is downloading right now to avoid doing it twice
        if fp in info.downloading:
            return (yield wad)

        # Download request checking media_to_download hook output first
        info.downloading.add(fp)
        yield _defer_sleep()
        result: FileInfo | Failure
        try:
            file_info = yield maybeDeferred(
                self.media_to_download, request, info, item=item
            )
            if file_info:
                # got a result without downloading
                result = file_info
            else:
                # download the result
                result = yield self._check_media_to_download(request, info, item=item)
        except Exception:
            result = Failure()
            logger.exception(result)
        self._cache_result_and_execute_waiters(result, fp, info)
        return (yield wad)  # it must return wad at last

    def _modify_media_request(self, request: Request) -> None:
        if self.handle_httpstatus_list:
            request.meta["handle_httpstatus_list"] = self.handle_httpstatus_list
        else:
            request.meta["handle_httpstatus_all"] = True

    @inlineCallbacks
    def _check_media_to_download(  # pylint: disable=inconsistent-return-statements
        self, request: Request, info: SpiderInfo, item: Any
    ) -> Generator[Deferred[Any], Any, FileInfo]:
        try:
            if self.download_func:
                # this ugly code was left only to support tests. TODO: remove
                response = yield maybeDeferred(self.download_func, request, info.spider)
            else:
                self._modify_media_request(request)
                assert self.crawler.engine
                response = yield deferred_from_coro(
                    self.crawler.engine.download_async(request)
                )
            return self.media_downloaded(response, request, info, item=item)
        except Exception:
            failure = self.media_failed(Failure(), request, info)
            if isinstance(failure, Failure):
                warnings.warn(
                    f"{global_object_name(self.media_failed)} returned a Failure instance."
                    f" This is deprecated, please raise an exception instead, e.g. via failure.raiseException().",
                    category=ScrapyDeprecationWarning,
                    stacklevel=2,
                )
                failure.raiseException()

    def _cache_result_and_execute_waiters(
        self, result: FileInfo | Failure, fp: bytes, info: SpiderInfo
    ) -> None:
        if isinstance(result, Failure):
            # minimize cached information for failure
            result.cleanFailure()
            result.frames = []
            if twisted_version < Version("twisted", 24, 10, 0):
                result.stack = []  # type: ignore[method-assign]
            # This code fixes a memory leak by avoiding to keep references to
            # the Request and Response objects on the Media Pipeline cache.
            #
            # What happens when the media_downloaded callback raises an
            # exception, for example a FileException('download-error') when
            # the Response status code is not 200 OK, is that the original
            # StopIteration exception (which in turn contains the failed
            # Response and by extension, the original Request) gets encapsulated
            # within the FileException context.
            #
            # Originally, Scrapy was using twisted.internet.defer.returnValue
            # inside functions decorated with twisted.internet.defer.inlineCallbacks,
            # encapsulating the returned Response in a _DefGen_Return exception
            # instead of a StopIteration.
            #
            # To avoid keeping references to the Response and therefore Request
            # objects on the Media Pipeline cache, we should wipe the context of
            # the encapsulated exception when it is a StopIteration instance
            context = getattr(result.value, "__context__", None)
            if isinstance(context, StopIteration):
                result.value.__context__ = None

        info.downloading.remove(fp)
        info.downloaded[fp] = result  # cache result
        for wad in info.waiting.pop(fp):
            if isinstance(result, Failure):
                call_later(_DEFER_DELAY, wad.errback, result)
            else:
                call_later(_DEFER_DELAY, wad.callback, result)

    # Overridable Interface
    @abstractmethod
    def media_to_download(
        self, request: Request, info: SpiderInfo, *, item: Any = None
    ) -> Deferred[FileInfo | None] | None:
        """Check request before starting download"""
        raise NotImplementedError

    @abstractmethod
    def get_media_requests(self, item: Any, info: SpiderInfo) -> list[Request]:
        """Returns the media requests to download"""
        raise NotImplementedError

    @abstractmethod
    def media_downloaded(
        self,
        response: Response,
        request: Request,
        info: SpiderInfo,
        *,
        item: Any = None,
    ) -> FileInfo:
        """Handler for success downloads"""
        raise NotImplementedError

    @abstractmethod
    def media_failed(
        self, failure: Failure, request: Request, info: SpiderInfo
    ) -> Failure:
        """Handler for failed downloads"""
        raise NotImplementedError

    def item_completed(
        self, results: list[FileInfoOrError], item: Any, info: SpiderInfo
    ) -> Any:
        """Called per item when all media requests has been processed"""
        if self.LOG_FAILED_RESULTS:
            for ok, value in results:
                if not ok:
                    assert isinstance(value, Failure)
                    logger.error(
                        "%(class)s found errors processing %(item)s",
                        {"class": self.__class__.__name__, "item": item},
                        exc_info=failure_to_exc_info(value),
                        extra={"spider": info.spider},
                    )
        return item

    @abstractmethod
    def file_path(
        self,
        request: Request,
        response: Response | None = None,
        info: SpiderInfo | None = None,
        *,
        item: Any = None,
    ) -> str:
        """Returns the path where downloaded media should be stored"""
        raise NotImplementedError

def _process_request(
    self, request: Request, info: SpiderInfo, item: Any
) -> Generator[Deferred[Any], Any, FileInfo]:
    fp = self._fingerprinter.fingerprint(request)

    eb = request.errback
    request.callback = NO_CALLBACK
    request.errback = None

    # Return cached result if request was already seen
    if fp in info.downloaded:
        yield _defer_sleep()
        cached_result = info.downloaded[fp]
        if isinstance(cached_result, Failure):
            if eb:
                return eb(cached_result)
            cached_result.raiseException()
        return cached_result

    # Otherwise, wait for result
    wad: Deferred[FileInfo] = Deferred()
    if eb:
        wad.addErrback(eb)
    info.waiting[fp].append(wad)

    # Check if request is downloading right now to avoid doing it twice
    if fp in info.downloading:
        return (yield wad)

    # Download request checking media_to_download hook output first
    info.downloading.add(fp)
    yield _defer_sleep()
    result: FileInfo | Failure
    try:
        file_info = yield maybeDeferred(
            self.media_to_download, request, info, item=item
        )
        if file_info:
            # got a result without downloading
            result = file_info
        else:
            # download the result
            result = yield self._check_media_to_download(request, info, item=item)
    except Exception:
        result = Failure()
        logger.exception(result)
    self._cache_result_and_execute_waiters(result, fp, info)
    return (yield wad)  # it must return wad at last

def _get_head_plugin(self) -> Any:
    prev = self.file
    for plugin in self.plugins[::-1]:
        prev = plugin(prev, self.feed_options)
    return prev

def stop(self):
    self.proc.kill()
    self.proc.communicate()

async def execute(
    self,
    *,
    command: Command,
    path: str,
    file_text: str | None = None,
    view_range: list[int] | None = None,
    old_str: str | None = None,
    new_str: str | None = None,
    insert_line: int | None = None,
    **kwargs: Any,
) -> str:
    """Execute a file operation command."""
    # Get the appropriate file operator
    operator = self._get_operator()

    # Validate path and command combination
    await self.validate_path(command, Path(path), operator)

    # Execute the appropriate command
    if command == "view":
        result = await self.view(path, view_range, operator)
    elif command == "create":
        if file_text is None:
            raise ToolError("Parameter `file_text` is required for command: create")
        await operator.write_file(path, file_text)
        self._file_history[path].append(file_text)
        result = ToolResult(output=f"File created successfully at: {path}")
    elif command == "str_replace":
        if old_str is None:
            raise ToolError(
                "Parameter `old_str` is required for command: str_replace"
            )
        result = await self.str_replace(path, old_str, new_str, operator)
    elif command == "insert":
        if insert_line is None:
            raise ToolError(
                "Parameter `insert_line` is required for command: insert"
            )
        if new_str is None:
            raise ToolError("Parameter `new_str` is required for command: insert")
        result = await self.insert(path, insert_line, new_str, operator)
    elif command == "undo_edit":
        result = await self.undo_edit(path, operator)
    else:
        # This should be caught by type checking, but we include it for safety
        raise ToolError(
            f'Unrecognized command {command}. The allowed commands for the {self.name} tool are: {", ".join(get_args(Command))}'
        )

    return str(result)

async def view(
    self,
    path: PathLike,
    view_range: Optional[List[int]] = None,
    operator: FileOperator = None,
) -> CLIResult:
    """Display file or directory content."""
    # Determine if path is a directory
    is_dir = await operator.is_directory(path)

    if is_dir:
        # Directory handling
        if view_range:
            raise ToolError(
                "The `view_range` parameter is not allowed when `path` points to a directory."
            )

        return await self._view_directory(path, operator)
    else:
        # File handling
        return await self._view_file(path, operator, view_range)

async def undo_edit(
    self, path: PathLike, operator: FileOperator = None
) -> CLIResult:
    """Revert the last edit made to a file."""
    if not self._file_history[path]:
        raise ToolError(f"No edit history found for {path}.")

    old_text = self._file_history[path].pop()
    await operator.write_file(path, old_text)

    return CLIResult(
        output=f"Last edit to {path} undone successfully. {self._make_output(old_text, str(path))}"
    )

def __init__(
    self, name: str = '', size: int = 0, readonly: bool = False,
    mode: int = stat.S_IREAD | stat.S_IWRITE,
    prefix: str = 'kitty-',
    unlink_on_exit: bool = False, ignore_close_failure: bool = False
):
    self.unlink_on_exit = unlink_on_exit
    self.ignore_close_failure = ignore_close_failure
    if size < 0:
        raise TypeError("'size' must be a non-negative integer")
    if size and name:
        raise TypeError('Cannot specify both name and size')
    if not name:
        flags = os.O_CREAT | os.O_EXCL
        if not size:
            raise TypeError("'size' must be > 0")
    else:
        flags = 0
    flags |= os.O_RDONLY if readonly else os.O_RDWR

    tries = 30
    while not name and tries > 0:
        tries -= 1
        q = make_filename(prefix)
        try:
            self._fd = shm_open(q, flags, mode)
            name = q
        except FileExistsError:
            continue
    if tries <= 0:
        raise OSError(f'Failed to create a uniquely named SHM file, try shortening the prefix from: {prefix}')
    if self._fd < 0:
        self._fd = shm_open(name, flags, mode)
    self._name = name
    try:
        if flags & os.O_CREAT and size:
            if hasattr(os, 'posix_fallocate'):
                os.posix_fallocate(self._fd, 0, size)
            else:
                os.ftruncate(self._fd, size)
        self.stats = os.fstat(self._fd)
        size = self.stats.st_size
        self._mmap = mmap.mmap(self._fd, size, access=mmap.ACCESS_READ if readonly else mmap.ACCESS_WRITE)
    except OSError:
        self.unlink()
        raise

    self._size = size

