class ResultConsumer(BaseResultConsumer):
    _pubsub = None

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._get_key_for_task = self.backend.get_key_for_task
        self._decode_result = self.backend.decode_result
        self._ensure = self.backend.ensure
        self._connection_errors = self.backend.connection_errors
        self.subscribed_to = set()

    def on_after_fork(self):
        try:
            self.backend.client.connection_pool.reset()
            if self._pubsub is not None:
                self._pubsub.close()
        except KeyError as e:
            logger.warning(str(e))
        super().on_after_fork()

    def _reconnect_pubsub(self):
        self._pubsub = None
        self.backend.client.connection_pool.reset()
        # task state might have changed when the connection was down so we
        # retrieve meta for all subscribed tasks before going into pubsub mode
        if self.subscribed_to:
            metas = self.backend.client.mget(self.subscribed_to)
            metas = [meta for meta in metas if meta]
            for meta in metas:
                self.on_state_change(self._decode_result(meta), None)
        self._pubsub = self.backend.client.pubsub(
            ignore_subscribe_messages=True,
        )
        # subscribed_to maybe empty after on_state_change
        if self.subscribed_to:
            self._pubsub.subscribe(*self.subscribed_to)
        else:
            self._pubsub.connection = self._pubsub.connection_pool.get_connection(
                'pubsub', self._pubsub.shard_hint
            )
            # even if there is nothing to subscribe, we should not lose the callback after connecting.
            # The on_connect callback will re-subscribe to any channels we previously subscribed to.
            self._pubsub.connection.register_connect_callback(self._pubsub.on_connect)

    @contextmanager
    def reconnect_on_error(self):
        try:
            yield
        except self._connection_errors:
            try:
                self._ensure(self._reconnect_pubsub, ())
            except self._connection_errors:
                logger.critical(E_RETRY_LIMIT_EXCEEDED)
                raise

    def _maybe_cancel_ready_task(self, meta):
        if meta['status'] in states.READY_STATES:
            self.cancel_for(meta['task_id'])

    def on_state_change(self, meta, message):
        super().on_state_change(meta, message)
        self._maybe_cancel_ready_task(meta)

    def start(self, initial_task_id, **kwargs):
        self._pubsub = self.backend.client.pubsub(
            ignore_subscribe_messages=True,
        )
        self._consume_from(initial_task_id)

    def on_wait_for_pending(self, result, **kwargs):
        for meta in result._iter_meta(**kwargs):
            if meta is not None:
                self.on_state_change(meta, None)

    def stop(self):
        if self._pubsub is not None:
            self._pubsub.close()

    def drain_events(self, timeout=None):
        if self._pubsub:
            with self.reconnect_on_error():
                message = self._pubsub.get_message(timeout=timeout)
                if message and message['type'] == 'message':
                    self.on_state_change(self._decode_result(message['data']), message)
        elif timeout:
            time.sleep(timeout)

    def consume_from(self, task_id):
        if self._pubsub is None:
            return self.start(task_id)
        self._consume_from(task_id)

    def _consume_from(self, task_id):
        key = self._get_key_for_task(task_id)
        if key not in self.subscribed_to:
            self.subscribed_to.add(key)
            with self.reconnect_on_error():
                self._pubsub.subscribe(key)

    def cancel_for(self, task_id):
        key = self._get_key_for_task(task_id)
        self.subscribed_to.discard(key)
        if self._pubsub:
            with self.reconnect_on_error():
                self._pubsub.unsubscribe(key)

def close(self) -> None:
    if self.use_pty:
        os.close(self.stdin_m)
        os.close(self.stdin_s)

    try:
        if self.sigint_on_exit and not self._terminated:
            self.terminate()
        proc_return_code = self.proc.wait(timeout=self.join_timeout)

        # Locust does not perform a graceful shutdown on Windows since we send SIGTERM
        if not IS_WINDOWS and self.expect_return_code is not None and proc_return_code != self.expect_return_code:
            self.on_fail(
                f"Process exited with return code {proc_return_code}. Expected {self.expect_return_code} ({proc_return_code} != {self.expect_return_code})"
            )
    except subprocess.TimeoutExpired:
        self.proc.kill()
        self.proc.wait()
        self.on_fail(f"Process took more than {self.join_timeout} seconds to terminate.")

    self.stdout_reader.join(timeout=self.join_timeout)
    self.stderr_reader.join(timeout=self.join_timeout)

def terminate(self):
    if IS_WINDOWS:
        # Signals are hard on Windows
        sig = signal.SIGTERM
    else:
        sig = signal.SIGINT

    self.proc.send_signal(sig)
    self._terminated = True

def auth_required_if_enabled(self, view_func):
    """
    Decorator that can be used on custom route methods that will turn on Flask Login
    authentication if the ``--web-login`` flag is used. Example::

        @web_ui.app.route("/my_custom_route")
        @web_ui.auth_required_if_enabled
        def my_custom_route():
            return "custom response"
    """

    @wraps(view_func)
    def wrapper(*args, **kwargs):
        if self.web_login:
            try:
                session["auth_error"] = None
                session["auth_info"] = None
                return login_required(view_func)(*args, **kwargs)
            except Exception as e:
                logger.exception("Locust auth exception")
                return f"Locust auth exception: {e}<br/><br/>See https://docs.locust.io/en/stable/extending-locust.html#adding-authentication-to-the-web-ui for configuring authentication, or disable login by removing --web-login argument."
        else:
            return view_func(*args, **kwargs)

    return wrapper

def start_server(self):
    if self.tls_cert and self.tls_key:
        self.server = pywsgi.WSGIServer(
            (self.host, self.port), self.app, log=None, keyfile=self.tls_key, certfile=self.tls_cert
        )
    else:

        class RewriteFilter(logging.Filter):
            def filter(self, record) -> bool:
                msg = record.msg
                if "gevent._socket3.socket at" in msg and "Invalid HTTP method: '\x16\x03" in msg:
                    record.msg = f"An https request was made against Locust's Web UI (which was expecting http). Underlying error was: {record.msg}"
                return True

        logger.addFilter(RewriteFilter())
        self.server = pywsgi.WSGIServer((self.host, self.port), self.app, log=None, error_log=logger)

    self.server.serve_forever()

class BuildProcess:
    def __init__(self, main, deps_info):
        self.logger = logger
        self.main = main
        self.build_folder = self._concat(self.main, "build")
        self.deps_info = deps_info
        self.npm_modules = self._concat(self.main, "node_modules")
        self.package_lock = self._concat(self.main, "package-lock.json")
        self.package = self._concat(self.main, "package.json")
        self._parse_package(path=self.package)
        self.asset_paths = (self.deps_folder, self.npm_modules)

    def _parse_package(self, path):
        with open(path, "r", encoding="utf-8") as fp:
            package = json.load(fp)
            self.version = package["version"]
            self.name = package["name"]
            self.deps_folder = self._concat(self.main, os.pardir, "deps")
            self.deps = package["dependencies"]

    @staticmethod
    def _concat(*paths):
        return os.path.realpath(os.path.sep.join((path for path in paths if path)))

    @staticmethod
    def _clean_path(path):
        if os.path.exists(path):
            logger.warning("🚨 %s already exists, remove it!", path)
            try:
                if os.path.isfile(path):
                    os.remove(path)
                if os.path.isdir(path):
                    shutil.rmtree(path)
            except OSError:
                sys.exit(1)
        else:
            logger.warning("🚨 %s doesn't exist, no action taken", path)

    @job("clean all the previous assets generated by build tool")
    def clean(self):
        for path in self.asset_paths:
            self._clean_path(path)

    @job("run `npm ci`")
    def npm(self):
        """Job to install npm packages."""
        os.chdir(self.main)
        run_command_with_process("npm ci")

    @job("build the renderer in dev mode")
    def watch(self):
        os.chdir(self.main)
        os.system("npm run build:dev")

    @job("run the whole building process in sequence")
    def build(self, build=None):
        self.clean()
        self.npm()
        self.bundles(build)
        self.digest()

    @job("compute the hash digest for assets")
    def digest(self):
        if not os.path.exists(self.deps_folder):
            try:
                os.makedirs(self.deps_folder)
            except OSError:
                logger.exception("🚨 having issues manipulating %s", self.deps_folder)
                sys.exit(1)

        payload = {self.name: self.version}

        for folder in (self.deps_folder, self.build_folder):
            copies = tuple(
                _
                for _ in os.listdir(folder)
                if os.path.splitext(_)[-1] in {".js", ".map"}
            )
            logger.info("bundles in %s %s", folder, copies)

            for copy in copies:
                payload[f"SHA256 ({copy})"] = compute_hash(self._concat(folder, copy))

        with open(self._concat(self.main, "digest.json"), "w", encoding="utf-8") as fp:
            json.dump(payload, fp, sort_keys=True, indent=4, separators=(",", ":"))
        logger.info(
            "bundle digest in digest.json:\n%s",
            json.dumps(payload, sort_keys=True, indent=4),
        )

    @job("copy and generate the bundles")
    def bundles(self, build=None):  # pylint:disable=too-many-locals
        if not os.path.exists(self.deps_folder):
            try:
                os.makedirs(self.deps_folder)
            except OSError:
                logger.exception("🚨 having issues manipulating %s", self.deps_folder)
                sys.exit(1)

        self._parse_package(self.package_lock)

        getattr(self, "_bundles_extra", lambda: None)()

        versions = {
            "version": self.version,
            "package": self.name.replace(" ", "_").replace("-", "_"),
        }

        for scope, name, subfolder, filename, extras in self.deps_info:
            version = self.deps["/".join(filter(None, [scope, name]))]["version"]
            name_squashed = name.replace("-", "").replace(".", "")
            versions[name_squashed] = version

            logger.info("copy npm dependency => %s", filename)
            ext = "min.js" if "min" in filename.split(".") else "js"
            target = f"{name}@{version}.{ext}"

            shutil.copyfile(
                self._concat(self.npm_modules, scope, name, subfolder, filename),
                self._concat(self.deps_folder, target),
            )

            if extras:
                extras_str = '", "'.join(extras)
                versions[f"extra_{name_squashed}_versions"] = f'"{extras_str}"'

                for extra_version in extras:
                    url = f"https://unpkg.com/{name}@{extra_version}/umd/{filename}"
                    res = requests.get(url)
                    extra_target = f"{name}@{extra_version}.{ext}"
                    extra_path = self._concat(self.deps_folder, extra_target)
                    with open(extra_path, "wb") as fp:
                        fp.write(res.content)

        _script = "build:dev" if build == "local" else "build:js"
        logger.info("run `npm run %s`", _script)
        os.chdir(self.main)
        run_command_with_process(f"npm run {_script}")

        logger.info("generate the `__init__.py` from template and versions")
        with open(self._concat(self.main, "init.template"), encoding="utf-8") as fp:
            t = string.Template(fp.read())

        renderer_init = self._concat(self.deps_folder, os.pardir, "_dash_renderer.py")
        with open(renderer_init, "w", encoding="utf-8") as fp:
            fp.write(t.safe_substitute(versions))

def checkAndReloadIfNeeded(self):
    now = int(time.time() * 1000)
    if now - self.memory_cache["last_check"] < CACHE_CHECK_INTERVAL_MS:
        return
    self.memory_cache["last_check"] = now

    try:
        file_path = self.getCredentialFilePath()
        stat = file_path.stat()
        file_mod_time = int(stat.st_mtime * 1000)
        if file_mod_time > self.memory_cache["file_mod_time"]:
            await self.reloadCredentialsFromFile()
            self.memory_cache["file_mod_time"] = file_mod_time
    except FileNotFoundError:
        self.memory_cache["file_mod_time"] = 0
    except Exception as e:
        self.memory_cache["credentials"] = None
        raise TokenManagerError(TokenError.FILE_ACCESS_ERROR, str(e), e)

    def _load_plugin(self, plugin_path, args=None, config=None):
        """Load the plugin, init it and add to the _plugin dict."""
        # Load the plugin class
        try:
            # Import the plugin
            plugin = import_module('glances.plugins.' + plugin_path)
            # Init and add the plugin to the dictionary
            if hasattr(plugin, 'PluginModel'):
                # Old fashion way to load the plugin (before Glances 5.0)
                # Should be removed in Glances 5.0 - see #3170
                self._plugins[plugin_path] = getattr(plugin, 'PluginModel')(args=args, config=config)
                logger.warning(
                    f'The {plugin_path} plugin class name is "PluginModel" and it is deprecated, \
please rename it to "{plugin_path.capitalize()}Plugin"'
                )
            elif hasattr(plugin, plugin_path.capitalize() + 'Plugin'):
                # New fashion way to load the plugin (after Glances 5.0)
                self._plugins[plugin_path] = getattr(plugin, plugin_path.capitalize() + 'Plugin')(
                    args=args, config=config
                )
        except Exception as e:
            # If a plugin can not be loaded, display a critical message
            # on the console but do not crash
            logger.critical(f"Error while initializing the {plugin_path} plugin ({e})")
            logger.error(traceback.format_exc())
            # An error occurred, disable the plugin
            if args is not None:
                setattr(args, 'disable_' + plugin_path, False)
        else:
            # Manage the default status of the plugin (enable or disable)
            if args is not None:
                # If the all keys are set in the disable_plugin option then look in the enable_plugin option
                if getattr(args, 'disable_all', False):
                    logger.debug('%s => %s', plugin_path, getattr(args, 'enable_' + plugin_path, False))
                    setattr(args, 'disable_' + plugin_path, not getattr(args, 'enable_' + plugin_path, False))
                else:
                    setattr(args, 'disable_' + plugin_path, getattr(args, 'disable_' + plugin_path, False))

def load_additional_plugins(self, args=None, config=None):
    """Load additional plugins if defined"""

    def get_addl_plugins(self, plugin_path):
        """Get list of additional plugins"""
        _plugin_list = []
        for plugin in os.listdir(plugin_path):
            path = os.path.join(plugin_path, plugin)
            if os.path.isdir(path) and not path.startswith('__'):
                # Poor man's walk_pkgs - can't use pkgutil as the module would be already imported here!
                for fil in pathlib.Path(path).glob('*.py'):
                    if fil.is_file():
                        with open(fil) as fd:
                            # The first test should be removed in Glances 5.x - see #3170
                            if 'PluginModel' in fd.read() or plugin.capitalize() + 'Plugin' in fd.read():
                                _plugin_list.append(plugin)
                                break

        return _plugin_list

    path = None
    # Skip section check as implied by has_option
    if config and config.parser.has_option('global', 'plugin_dir'):
        path = config.parser['global']['plugin_dir']

    if args and 'plugin_dir' in args and args.plugin_dir:
        path = args.plugin_dir

    if path:
        # Get list before starting the counter
        _sys_path = sys.path
        start_duration = Counter()
        # Ensure that plugins can be found in plugin_dir
        sys.path.insert(0, path)
        for plugin in get_addl_plugins(self, path):
            if plugin in sys.modules:
                logger.warn(f"Plugin {plugin} already in sys.modules, skipping (workaround: rename plugin)")
            else:
                start_duration.reset()
                try:
                    _mod_loaded = import_module(plugin + '.model')
                    self._plugins[plugin] = _mod_loaded.PluginModel(args=args, config=config)
                    logger.debug(f"Plugin {plugin} started in {start_duration.get()} seconds")
                except Exception as e:
                    # If a plugin can not be loaded, display a critical message
                    # on the console but do not crash
                    logger.critical(f"Error while initializing the {plugin} plugin ({e})")
                    logger.error(traceback.format_exc())
                    # An error occurred, disable the plugin
                    if args:
                        setattr(args, 'disable_' + plugin, False)

        sys.path = _sys_path
        # Log plugins list
        logger.debug(f"Active additional plugins list: {self.getPluginsList()}")

def end(self):
    """End of the Glances stats."""
    # Close export modules
    for e in self._exports:
        self._exports[e].exit()
    # Close plugins
    for p in self._plugins:
        self._plugins[p].exit()
        self._plugins[p].exit()

def test_api_importable():
    """
    Check that all submodules listed higher up in this file can be imported
    Note that if a PRIVATE_BUT_PRESENT_MODULES entry goes missing, it may
    simply need to be removed from the list (deprecation may or may not be
    needed - apply common sense).
    """
    def check_importable(module_name):
        try:
            importlib.import_module(module_name)
        except (ImportError, AttributeError):
            return False

        return True

    module_names = []
    for module_name in PUBLIC_MODULES:
        if not check_importable(module_name):
            module_names.append(module_name)

    if module_names:
        raise AssertionError("Modules in the public API that cannot be "
                             f"imported: {module_names}")

    with warnings.catch_warnings(record=True):
        warnings.simplefilter('always', category=DeprecationWarning)
        warnings.simplefilter('always', category=ImportWarning)
        for module_name in PRIVATE_BUT_PRESENT_MODULES:
            if not check_importable(module_name):
                module_names.append(module_name)

    if module_names:
        raise AssertionError("Modules that are not really public but looked "
                             "public and can not be imported: "
                             f"{module_names}")

def load(self) -> Image.core.PixelAccess | None:
    """Load image data based on tile list"""

    if not self.tile and self._im is None:
        msg = "cannot load this image"
        raise OSError(msg)

    pixel = Image.Image.load(self)
    if not self.tile:
        return pixel

    self.map: mmap.mmap | None = None
    use_mmap = self.filename and len(self.tile) == 1

    readonly = 0

    # look for read/seek overrides
    if hasattr(self, "load_read"):
        read = self.load_read
        # don't use mmap if there are custom read/seek functions
        use_mmap = False
    else:
        read = self.fp.read

    if hasattr(self, "load_seek"):
        seek = self.load_seek
        use_mmap = False
    else:
        seek = self.fp.seek

    if use_mmap:
        # try memory mapping
        decoder_name, extents, offset, args = self.tile[0]
        if isinstance(args, str):
            args = (args, 0, 1)
        if (
            decoder_name == "raw"
            and isinstance(args, tuple)
            and len(args) >= 3
            and args[0] == self.mode
            and args[0] in Image._MAPMODES
        ):
            if offset < 0:
                msg = "Tile offset cannot be negative"
                raise ValueError(msg)
            try:
                # use mmap, if possible
                import mmap

                with open(self.filename) as fp:
                    self.map = mmap.mmap(fp.fileno(), 0, access=mmap.ACCESS_READ)
                if offset + self.size[1] * args[1] > self.map.size():
                    msg = "buffer is not large enough"
                    raise OSError(msg)
                self.im = Image.core.map_buffer(
                    self.map, self.size, decoder_name, offset, args
                )
                readonly = 1
                # After trashing self.im,
                # we might need to reload the palette data.
                if self.palette:
                    self.palette.dirty = 1
            except (AttributeError, OSError, ImportError):
                self.map = None

    self.load_prepare()
    err_code = -3  # initialize to unknown error
    if not self.map:
        # sort tiles in file order
        self.tile.sort(key=_tilesort)

        # FIXME: This is a hack to handle TIFF's JpegTables tag.
        prefix = getattr(self, "tile_prefix", b"")

        # Remove consecutive duplicates that only differ by their offset
        self.tile = [
            list(tiles)[-1]
            for _, tiles in itertools.groupby(
                self.tile, lambda tile: (tile[0], tile[1], tile[3])
            )
        ]
        for i, (decoder_name, extents, offset, args) in enumerate(self.tile):
            seek(offset)
            decoder = Image._getdecoder(
                self.mode, decoder_name, args, self.decoderconfig
            )
            try:
                decoder.setimage(self.im, extents)
                if decoder.pulls_fd:
                    decoder.setfd(self.fp)
                    err_code = decoder.decode(b"")[1]
                else:
                    b = prefix
                    while True:
                        read_bytes = self.decodermaxblock
                        if i + 1 < len(self.tile):
                            next_offset = self.tile[i + 1].offset
                            if next_offset > offset:
                                read_bytes = next_offset - offset
                        try:
                            s = read(read_bytes)
                        except (IndexError, struct.error) as e:
                            # truncated png/gif
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = "image file is truncated"
                                raise OSError(msg) from e

                        if not s:  # truncated jpeg
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = (
                                    "image file is truncated "
                                    f"({len(b)} bytes not processed)"
                                )
                                raise OSError(msg)

                        b = b + s
                        n, err_code = decoder.decode(b)
                        if n < 0:
                            break
                        b = b[n:]
            finally:
                # Need to cleanup here to prevent leaks
                decoder.cleanup()

    self.tile = []
    self.readonly = readonly

    self.load_end()

    if self._exclusive_fp and self._close_exclusive_fp_after_loading:
        self.fp.close()
    self.fp = None

    if not self.map and not LOAD_TRUNCATED_IMAGES and err_code < 0:
        # still raised if decoder fails to return anything
        raise _get_oserror(err_code, encoder=False)

    return Image.Image.load(self)

def load(self) -> Image.core.PixelAccess | None:
    if self.tile:
        args = self.tile[0].args
        assert isinstance(args, tuple)
        compression, band = args

        self.fp.seek(self.tile[0].offset)

        # Copy image data to temporary file
        o = BytesIO()
        if compression == "raw":
            # To simplify access to the extracted file,
            # prepend a PPM header
            o.write(b"P5\n%d %d\n255\n" % self.size)
        while True:
            type, size = self.field()
            if type != (8, 10):
                break
            while size > 0:
                s = self.fp.read(min(size, 8192))
                if not s:
                    break
                o.write(s)
                size -= len(s)

        with Image.open(o) as _im:
            if band is not None:
                bands = [Image.new("L", _im.size)] * Image.getmodebands(self.mode)
                bands[band] = _im
                _im = Image.merge(self.mode, bands)
            else:
                _im.load()
            self.im = _im.im
        self.tile = []
    return ImageFile.ImageFile.load(self)

def forward_model(model, model_name, preprocess_val, image_batch, text_batch):
    y = []
    tokenizer = open_clip.get_tokenizer(model_name)
    with torch.no_grad():
        for x_im, x_txt in zip(image_batch, text_batch):
            x_im = torch.stack([preprocess_val(im) for im in x_im])
            x_txt = tokenizer(x_txt)
        y.append(model(x_im, x_txt))
    if type(y[0]) == dict:
        out = {}
        for key in y[0].keys():
            out[key] = torch.stack([batch_out[key] for batch_out in y])
    else:
        out = []
        for i in range(len(y[0])):
            out.append(torch.stack([batch_out[i] for batch_out in y]))
    return out

